// Evaluate DOT Factors
// Reads the three accident-classification answers plus the inbound event type,
// and sets the booleans the two downstream routers branch on.
let majorAccident   = ZT.getVariableValue("sf_Specimen_Requested__c", "");
let aircraftDestroyed = ZT.getVariableValue("sf_Is_the_aircraft_destroyed__c", "");
let fatalities      = ZT.getVariableValue("sf_Are_there_any_fatalities__c", "");
let eventType       = ZT.getVariableValue("sf_Event_Type", "");

let isDotAccident = majorAccident === "Yes" || aircraftDestroyed === "Yes" || fatalities === "Yes";

ZT.setFormData("is_dot_accident", isDotAccident);
ZT.setFormData("is_suspicion", eventType === "Suspicion");

