// Evaluate No-Testing Factors
// Confirms the four Delta no-testing conditions and stages one boolean for the router.
let minor      = ZT.getVariableValue("sf_Minor_or_cosmetic_damage__c", "");
let over32     = ZT.getVariableValue("sf_Over_32_hours_since_incident__c", "");
let weather    = ZT.getVariableValue("sf_Incident_caused_by_weather__c", "");
let mechanical = ZT.getVariableValue("sf_Fault_due_to_mechanical_equipment_fail__c", "");

let noTestingConfirmed = minor === "Yes" && over32 === "Yes" && weather === "No" && mechanical === "No";
ZT.setFormData("no_testing_confirmed", noTestingConfirmed);

// If confirmed, stage the definitive determination now so the summary/email never
// falls back to the 'unavailable' box on the no-testing path.
if (noTestingConfirmed) {
    ZT.setTransformData("testing_classification", "NON_DOT_NO_TESTING");
    ZT.setTransformData("testing_summary_html",
        '<div style="border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;padding:10px 12px;margin-top:10px;font-size:14px;line-height:1.45;color:#111827;">'
        + '<div style="font-weight:700;margin-bottom:4px;">No Testing Required</div>'
        + '<div>No-testing factors confirmed: minor/cosmetic damage, over 32 hours since the incident, not weather-related, and employee not at fault due to mechanical/equipment failure.</div></div>');
}

