function buildDamageRecord() {
    return {
        damage_type,
        fault: ZT.getVariableValue('fault', ''),
        elapsed_hours: ZT.getVariableValue('elapsed_hours', '') || ZT.getVariableValue('hours_elapsed', ''),
        sf_Additional_Notes__c: ZT.getVariableValue('sf_Additional_Notes__c', ''),
        // Aircraft
        sf_Aircraft_Ground_Damage_Requires_Maint__c: ZT.getVariableValue('sf_Aircraft_Ground_Damage_Requires_Maint__c', ''),
        sf_Aircraft_Out_of_Service__c: ZT.getVariableValue('sf_Aircraft_Out_of_Service__c', ''),
        aircraft_employee_fault: ZT.getVariableValue('aircraft_employee_fault', ''),
        // GSE
        sf_Equip_removed_from_Service__c: ZT.getVariableValue('sf_Equip_removed_from_Service__c', ''),
        sf_Equipment_Undergo_Maintenance_Inspection__c: ZT.getVariableValue('sf_Equipment_Undergo_Maintenance_Inspection__c', ''),
        sf_Shear_Pin_Damage__c: ZT.getVariableValue('sf_Shear_Pin_Damage__c', ''),
        // Property/Structure Damage
        sf_Airport_Property_Structural_Damage__c: ZT.getVariableValue('sf_Airport_Property_Structural_Damage__c', ''),
        sf_Extensive_Prop_Damage_Disrupts_Ops__c: ZT.getVariableValue('sf_Extensive_Prop_Damage_Disrupts_Ops__c', ''),
        // Injuries
        sf_Personal_Injury__c: ZT.getVariableValue('sf_Personal_Injury__c', ''),
        injury_medical_care: ZT.getVariableValue('injury_medical_care', ''),
        // Flight Delay
        sf_Flight_Delays__c: ZT.getVariableValue('sf_Flight_Delays__c', ''),
        // Vehicles
        sf_Vehicle_Damage__c: ZT.getVariableValue('sf_Vehicle_Damage__c', ''),
    };
}

let record = buildDamageRecord();
let final_records = transforms.final_records || [];
final_records.push(record);
ZT.setTransformData("final_records", final_records)

